// ─── 编辑器 op 目录（由 ai/ops.ts 的 opCatalog() 生成） ────────────────
//
// 这些 op 由页面内的 apply_ops 执行（单事务、一次撤销）。执行点不实现它们：
// 无页面时 apply_ops 回 command.page-unavailable。这里只作为 guide 的说明书，
// 让模型不必读长 description 就能写对 op。

export interface EditorOpSpec {
  name: string
  target: 'none' | 'optional' | 'required'
  signature: string
  keys: string[]
}

export const EDITOR_OPS: EditorOpSpec[] = [
  { name: "setFont", target: "required", signature: "{ op: \"setFont\", target, bold?, italic?, underline?, strike?, color?: \"#RRGGBB\"|null, highlight?, fontSize?: pt|null, fontFamily?: string|null, baseline?: \"superscript\"|\"subscript\"|\"none\"|null, link?: {url}|null }  // run-level style of the targeted blocks (only the selected characters when the target is a partial selection); a present field is set, null clears it, absent fields stay; fontFamily applies to its own script slot (an East Asian font keeps the run's Latin font and vice versa)", keys: ["bold","italic","underline","strike","color","highlight","fontSize","fontFamily","baseline","link"] },
  { name: "setMatchedFont", target: "optional", signature: "{ op: \"setMatchedFont\", text?, matchCase?, matchColor?: \"#RRGGBB\"|\"auto\", matchFontSize?: pt|\"default\", target?, bold?, italic?, underline?, strike?, color?: \"#RRGGBB\"|null, highlight?, fontSize?: pt|null, fontFamily?: string|null, baseline?: \"superscript\"|\"subscript\"|\"none\"|null, link?: {url}|null }  // character-level: styles only the runs that match (not the whole block) — occurrences of text, and/or runs currently in matchColor / at matchFontSize (as shown by read_blocks spans); give at least one of text / matchColor / matchFontSize; target narrows the scanned blocks, omitted = whole document (table cells included)", keys: ["text","matchCase","matchColor","matchFontSize","bold","italic","underline","strike","color","highlight","fontSize","fontFamily","baseline","link"] },
  { name: "setParagraphFormat", target: "required", signature: "{ op: \"setParagraphFormat\", target, align?: \"left\"|\"center\"|\"right\"|\"justify\"|null, lineSpacing?, indentLeft?, indentRight?, indentFirstLine?, spaceBefore?, spaceAfter?, pageBreakBefore?: boolean, shadingFill?: \"#RRGGBB\"|null, borders?: subset of \"tblr\"|null, tabs?: [{ pos: twips|\"6.5in\", align?: \"left\"|\"center\"|\"right\"|\"decimal\"|\"bar\", leader?: \"none\"|\"dot\"|\"hyphen\"|\"underscore\"|\"middleDot\", clear?: true }]|null }  // paragraph format of the targeted blocks (whole blocks, even for a partial selection); lengths in twips, lineSpacing as a multiple; indentFirstLine positive = first-line indent, negative = hanging; a two-character CJK indent ≈ font size in pt × 40 twips; tabs replaces the paragraph's own stops ([] / null clears them, clear: true cancels a style stop); a tab character in HTML is <span data-tab></span>", keys: ["align","lineSpacing","indentLeft","indentRight","indentFirstLine","spaceBefore","spaceAfter","pageBreakBefore","shadingFill","borders","tabs"] },
  { name: "setHeadingLevel", target: "required", signature: "{ op: \"setHeadingLevel\", target, level: 0-6 }  // 0 = demote to body paragraph", keys: ["level"] },
  { name: "findReplace", target: "optional", signature: "{ op: \"findReplace\", find, replace, matchCase?, target? }  // plain-text find & replace inside runs (no cross-block matching); the replacement keeps the matched text's formatting — the right op for small in-place fixes; target narrows the scanned blocks (blockIndexes / scope:\"selection\" / nodeType), omitted = whole document", keys: ["find","replace","matchCase"] },
  { name: "deleteBlocks", target: "required", signature: "{ op: \"deleteBlocks\", target }", keys: [] },
  { name: "moveBlocks", target: "none", signature: "{ op: \"moveBlocks\", blockIndexes: number[], afterBlockIndex }  // move the blocks (relative order kept) after afterBlockIndex; -1 = start of document", keys: ["blockIndexes","afterBlockIndex"] },
  { name: "setList", target: "required", signature: "{ op: \"setList\", target, kind?: \"bullet\"|\"number\" }  // paragraphs to list items (default bullet); heading blocks are not converted", keys: ["kind"] },
  { name: "clearList", target: "required", signature: "{ op: \"clearList\", target }  // list items back to body paragraphs", keys: [] },
  { name: "setImageProperties", target: "required", signature: "{ op: \"setImageProperties\", target, widthPx?, heightPx?, align?: \"left\"|\"center\"|\"right\"|null }  // image blocks only (target nodeType \"image\"); giving one dimension scales the other proportionally", keys: ["widthPx","heightPx","align"] },
  { name: "insertToc", target: "none", signature: "{ op: \"insertToc\", afterBlockIndex }  // insert a TOC field after that block (-1 = start of document); entries come from the current headings, Word computes page numbers on open; fails if the document has no headings", keys: ["afterBlockIndex"] },
  { name: "insertField", target: "required", signature: "{ op: \"insertField\", target, type: \"SEQ\"|\"REF\"|\"PAGEREF\"|\"DATE\"|\"TIME\"|\"MERGEFIELD\"|\"IF\"|\"PAGE\"|\"NUMPAGES\"|\"AUTHOR\"|..., args?: string, result?: string, position?: \"start\"|\"end\", afterText?: string }  // insert a Word field into exactly one paragraph, at its end unless position or afterText says otherwise; args is the instruction after the keyword ({ SEQ Figure \\* ARABIC } = type \"SEQ\", args \"Figure \\* ARABIC\"). Computed here: SEQ (visible fields with that identifier so far + 1), REF/PAGEREF (the bookmarked paragraph; insertBookmark creates one), DATE/TIME (now, \\@ picture), MERGEFIELD («Name»), IF with literal operands; PAGE/NUMPAGES show \"1\"; anything else needs result, the text shown until Word updates it. Fields only Word can compute are marked dirty and refresh when the file opens in Word", keys: ["type","args","result","position","afterText"] },
  { name: "insertBookmark", target: "required", signature: "{ op: \"insertBookmark\", target, name }  // bookmark exactly one paragraph (name: letters, digits, underscore, up to 40 characters, unique) so REF / PAGEREF fields can point at it", keys: ["name"] },
  { name: "updateFields", target: "none", signature: "{ op: \"updateFields\", scope?: \"all\"|\"SEQ\"|\"REF\"|\"DATE\" }  // recompute the inline fields the editor can: SEQ numbering in document order, REF results from their bookmarks, DATE/TIME to now; with scope \"all\" every other field (PAGE, NUMPAGES, AUTHOR...) is marked dirty so Word recomputes it on open. Table-of-contents blocks are untouched (insertToc rebuilds one)", keys: ["scope"] },
  { name: "insertTableRow", target: "required", signature: "{ op: \"insertTableRow\", target, row, position?: \"before\"|\"after\", count? }  // target must match one native table (nodeType \"table\" and/or blockIndexes); row is 0-based; new rows copy the neighbouring row's cell shading/borders (default: after)", keys: ["row","position","count"] },
  { name: "deleteTableRow", target: "required", signature: "{ op: \"deleteTableRow\", target, row, count? }  // target must match one native table (nodeType \"table\" and/or blockIndexes); row is 0-based; cells merged across the row shrink", keys: ["row","count"] },
  { name: "insertTableColumn", target: "required", signature: "{ op: \"insertTableColumn\", target, col, position?: \"before\"|\"after\", count? }  // target must match one native table; col is a 0-based grid column; the new column takes the neighbouring column's width and cell formatting (default: after)", keys: ["col","position","count"] },
  { name: "deleteTableColumn", target: "required", signature: "{ op: \"deleteTableColumn\", target, col, count? }  // target must match one native table; col is a 0-based grid column; cells merged across the column shrink", keys: ["col","count"] },
  { name: "mergeTableCells", target: "required", signature: "{ op: \"mergeTableCells\", target, range: { row, col, rowEnd?, colEnd? } }  // merge the rectangle (0-based grid coordinates, ends inclusive) into one cell; refused when an existing merged cell crosses the rectangle edge; the texts are kept as separate paragraphs", keys: ["range"] },
  { name: "splitTableCell", target: "required", signature: "{ op: \"splitTableCell\", target, cell: { row, col } }  // undo a merge: the cell becomes one cell per grid slot it covered; the text stays in the top-left one", keys: ["cell"] },
  { name: "setTableCellFormat", target: "required", signature: "{ op: \"setTableCellFormat\", target, range?: { row, col, rowEnd?, colEnd? }, fill?: \"#RRGGBB\"|null, vAlign?: \"top\"|\"center\"|\"bottom\"|null, width?: twips|\"2.5cm\"|\"1in\"|\"72pt\"|\"96px\", borders?: { all?, top?, left?, bottom?, right?: { style?: \"single\"|\"dashed\"|\"double\"|\"none\", width?: pt, color?: \"#RRGGBB\" }|null }|null }  // cells in the range (omitted = whole table); width sets the grid columns the range covers; borders: null = no borders on the cell, a side null = that side off", keys: ["range","fill","vAlign","width","borders"] },
  { name: "setTableStyle", target: "required", signature: "{ op: \"setTableStyle\", target, styleId?: string|null, look?: { firstRow?, lastRow?, firstColumn?, lastColumn?, bandedRows?, bandedColumns?: boolean } }  // styleId must be a table style defined in this document (docs read lists them as tableStyles); null removes the style; look toggles Word's Table Style Options", keys: ["styleId","look"] },
  { name: "applyStyle", target: "required", signature: "{ op: \"applyStyle\", target, styleId }  // paragraph style by id (or name) from styles.xml / define_style; a heading style turns the block into a heading of its level, another paragraph style turns a heading back into a paragraph; list items keep their numbering", keys: ["styleId"] },
]
